    args: [{ selector: "app-inscripciones", standalone: true, imports: [CommonModule, FormsModule, ReactiveFormsModule, IncidenciasPanelComponent, ConfirmDialogComponent, EstadoBadgeComponent, FormulariosComponent], template: `<section class="inscripciones ux-card">
  <div class="inscripciones-body">
      <div class="page-head mb-4">
        <div>
          <p class="ux-overline mb-1">Inscripciones</p>
          <h1 class="ux-page-title mb-1">{{ isAdminMode ? 'Inscripciones' : 'Inscripciones disponibles' }}</h1>
          <p class="text-muted mb-0">
            {{ isAdminMode ? 'Crea, revisa y edita formularios de inscripcion.' : 'Consulta las convocatorias abiertas y presenta tus inscripciones.' }}
          </p>
        </div>
      </div>

      <div class="alert alert-danger" *ngIf="error">{{ error }}</div>
      <div class="alert alert-success" *ngIf="success">{{ success }}</div>
      <div class="alert alert-warning" *ngIf="accionesAsociacionBloqueadasPorEjercicio">
        <strong>Ejercicio solo consulta.</strong> {{ mensajeEjercicioNoActivo }}
      </div>
      <div class="text-muted" *ngIf="loading">Cargando...</div>

      <div class="layout" *ngIf="!detailMode">
        <section class="detail list-page">
          <div class="section-head">
            <div>
              <h2 class="section-title mb-1">Listado de inscripciones</h2>
              <p class="text-muted mb-0">
                {{ isAdminMode ? 'Abre una inscripcion para editarla o revisar sus entradas.' : 'Elige una inscripcion para consultar documentacion, formulario y asociados inscritos.' }}
              </p>
            </div>
            <button
              class="ux-btn"
              type="button"
              *ngIf="isAdminMode && permissions.hasPermission('inscripciones:write')"
              (click)="crearNuevaInscripcion()"
            >
              Crear inscripcion
            </button>
          </div>
          <section class="inscription-filters" aria-label="Filtros de inscripciones">
            <label class="filter-search">Buscar inscripci\xF3n<input class="form-control form-control-sm" type="search" [(ngModel)]="busquedaInscripciones" (keyup.enter)="cargarPaginaInscripciones(true)" placeholder="T\xEDtulo o actividad" /></label>
            <label *ngIf="isAdminMode">Estado<select class="form-select form-select-sm" [(ngModel)]="filtroEstado" (ngModelChange)="cargarPaginaInscripciones(true)"><option value="">Todos</option><option value="borrador">Borrador</option><option value="abierta">Abierta</option><option value="cerrada">Cerrada</option></select></label>
            <label>Disponibilidad<select class="form-select form-select-sm" [(ngModel)]="filtroDisponibilidad" (ngModelChange)="cargarPaginaInscripciones(true)"><option value="">Todas</option><option value="activa">Activas</option><option value="cerrada">Plazo cerrado</option></select></label>
            <label>Ordenar<select class="form-select form-select-sm" [(ngModel)]="ordenInscripciones" (ngModelChange)="cargarPaginaInscripciones(true)"><option value="plazo_asc">Plazo m\xE1s pr\xF3ximo</option><option value="plazo_desc">Plazo m\xE1s lejano</option><option value="titulo_asc">T\xEDtulo A-Z</option></select></label>
            <div class="filter-action"><button class="ux-btn ux-btn-sm" type="button" (click)="cargarPaginaInscripciones(true)">Buscar</button></div>
          </section>
          <div class="inscription-list mb-4">
            <div
              *ngFor="let item of inscripciones"
              class="list-item"
              role="button"
              tabindex="0"
              (click)="openInscription(item)"
              (keydown.enter)="openInscription(item)"
              (keydown.space)="openInscription(item); $event.preventDefault()"
            >
              <div class="text-start">
                <p class="title mb-1">{{ item.titulo }}</p>
                <p class="subtitle mb-1 text-muted">{{ actividadDe(item)?.titulo || 'Sin actividad vinculada' }}</p>
                <div class="dates small text-muted">
                  <span>Publicada: {{ item.fechaPublicacion | date : 'dd/MM/y' }}</span>
                  <span class="ms-2">Limite: {{ item.fechaLimite | date : 'dd/MM/y' }}</span>
                  <app-estado-badge class="ms-2" *ngIf="isAdminMode" [estado]="item.estado"></app-estado-badge>
                </div>
                <div class="inscription-badges" *ngIf="!isAdminMode"><span class="availability-badge" [class.closed]="!isInscripcionDisponible(item)">{{ disponibilidadLabel(item) }}</span><span class="participation-badge" [class.registered]="item.inscrito">{{ item.inscrito ? 'Inscrito' : 'No inscrito' }}</span></div>
              </div>
              <div class="list-actions" *ngIf="isAdminMode" (click)="$event.stopPropagation()">
                <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="openInscription(item)">Ver detalle</button>
                <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="imprimirTodas(item)">Imprimir</button>
                <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="descargarTodas(item, 'csv')">Excel</button>
                <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="descargarTodas(item, 'pdf')">PDF</button>
              </div>
            </div>
          </div>
          <nav class="participant-pagination" *ngIf="paginacionInscripciones.totalPages > 1" aria-label="Paginaci\xF3n de inscripciones"><span class="text-muted small">P\xE1gina {{ paginacionInscripciones.page }} de {{ paginacionInscripciones.totalPages }}</span><div class="page-actions"><button class="ux-btn ux-btn-light ux-btn-sm" type="button" [disabled]="paginacionInscripciones.page === 1" (click)="cambiarPaginaInscripciones(-1)">Anterior</button><button class="ux-btn ux-btn-light ux-btn-sm" type="button" [disabled]="paginacionInscripciones.page === paginacionInscripciones.totalPages" (click)="cambiarPaginaInscripciones(1)">Siguiente</button></div></nav>
          <p class="text-muted mb-0" *ngIf="!inscripciones.length && !loading">No hay inscripciones disponibles.</p>
        </section>
      </div>

      <div class="layout" *ngIf="detailMode">
        <section class="detail">
          <button class="ux-btn ux-btn-secondary align-self-start" type="button" (click)="volverAlListado()">
            <i class="bi bi-arrow-left me-1"></i>
            Volver al listado
          </button>
          <form
            class="admin-panel mt-3"
            *ngIf="createMode && isAdminMode && permissions.hasPermission('inscripciones:write')"
            [formGroup]="inscripcionAdminForm"
            (ngSubmit)="crearInscripcion()"
          >
            <h3 class="section-title">Nueva inscripcion</h3>
            <label class="form-label">Titulo</label>
            <input class="form-control" formControlName="titulo" />
            <label class="form-label mt-2">Formulario reutilizable</label>
            <select class="form-select" formControlName="formularioId">
              <option value="">Formulario propio de esta inscripcion</option>
              <option *ngFor="let formulario of formularios" [value]="formulario.id">
                {{ formulario.nombre }} ({{ formulario.campos.length }} campo(s))
              </option>
            </select>
            <label class="form-label mt-2">Actividad vinculada</label>
            <select class="form-select" formControlName="actividadId">
              <option value="">Sin actividad vinculada</option>
              <option *ngFor="let actividad of actividades" [value]="actividad.id">{{ actividad.titulo }}</option>
            </select>
            <div class="row g-2 mt-1">
              <div class="col">
                <label class="form-label">Publicacion</label>
                <input type="date" class="form-control" formControlName="fechaPublicacion" />
              </div>
              <div class="col">
                <label class="form-label">Fecha limite</label>
                <input type="date" class="form-control" formControlName="fechaLimite" />
              </div>
            </div>
            <div class="d-flex gap-3 mt-3">
              <label class="form-check">
                <input type="checkbox" class="form-check-input" formControlName="adultos" />
                Adultos
              </label>
              <label class="form-check">
                <input type="checkbox" class="form-check-input" formControlName="infantiles" />
                Infantiles
              </label>
            </div>
            <div class="d-flex gap-2 mt-3 flex-wrap">
              <button class="ux-btn" type="submit" [disabled]="loading">Crear inscripcion</button>
              <button class="ux-btn ux-btn-secondary" type="button" (click)="volverAlListado()">Cancelar</button>
            </div>
          </form>

          <ng-container *ngIf="selectedInscription as inscription">
            <div class="detail-header d-flex align-items-start justify-content-between gap-3 flex-wrap">
              <div>
                <p class="ux-overline mb-1">Formulario</p>
                <h3 class="detail-title mb-1">{{ inscription.titulo }}</h3>
                <p class="text-muted mb-0">{{ actividadDe(inscription)?.titulo || 'Inscripcion sin actividad vinculada' }}</p>
              </div>
              <span class="type-badge">
                {{ inscription.tiposPermitidos.join(', ') }}
              </span>
            </div>

            <div class="alert alert-warning mt-3 mb-0" *ngIf="!isAdminMode && mensajeDisponibilidadInscripcion(inscription)">
              <i class="bi bi-clock-history me-1" aria-hidden="true"></i>
              {{ mensajeDisponibilidadInscripcion(inscription) }}
            </div>

            <div class="admin-tabs" *ngIf="isAdminMode">
              <button type="button" class="tab-button" [class.active]="adminTab === 'documentacion'" (click)="setAdminTab('documentacion')">
                Documentacion
              </button>
              <button type="button" class="tab-button" [class.active]="adminTab === 'gestion'" (click)="setAdminTab('gestion')">
                Gestion
              </button>
              <button type="button" class="tab-button" [class.active]="adminTab === 'inscritos'" (click)="setAdminTab('inscritos')">
                Inscritos
              </button>
            </div>

            <div class="inscription-steps" *ngIf="!isAdminMode" aria-label="Inscripcion paso a paso">
              <button type="button" class="step-pill" [class.active]="associationStep === 1" (click)="goAssociationStep(1)">
                <span>1</span>
                Documentacion
              </button>
              <button type="button" class="step-pill" [class.active]="associationStep === 2" (click)="goAssociationStep(2)">
                <span>2</span>
                Datos
              </button>
              <button type="button" class="step-pill" [class.active]="associationStep === 3" (click)="goAssociationStep(3)">
                <span>3</span>
                Participantes
              </button>
              <button type="button" class="step-pill" [class.active]="associationStep === 4" [disabled]="!miEntrada" (click)="goAssociationStep(4)">
                <span>4</span>
                Revisar
              </button>
              <button type="button" class="step-pill" [class.active]="associationStep === 5" [disabled]="!canSubmit || accionesAsociacionBloqueadasPorEjercicio" (click)="submit()">
                <span>5</span>
                Enviar
              </button>
            </div>

            <div class="documents mt-3" *ngIf="(isAdminMode && adminTab === 'documentacion') || (!isAdminMode && associationTab === 'documentacion')">
              <h3 class="section-title">{{ isAdminMode ? 'Documentos asociados' : 'Antes de inscribirte' }}</h3>
              <p class="text-muted" *ngIf="!isAdminMode">
                Lee las condiciones y documentos adjuntos. Despues podras rellenar los datos y seleccionar participantes.
              </p>
              <div class="document-list" *ngIf="adjuntos.length; else noDocs">
                <button class="document-item" type="button" *ngFor="let adjunto of adjuntos" (click)="abrirDocumento(adjunto)">
                  {{ adjunto.mimeType === 'application/pdf' ? 'PDF \xB7 ' : (adjunto.mimeType || '').startsWith('image/') ? 'Imagen \xB7 ' : 'Archivo \xB7 ' }}{{ adjunto.originalName || adjunto.fileName }}
                </button>
              </div>
              <div class="actions mt-3" *ngIf="!isAdminMode">
                <button class="ux-btn" type="button" (click)="goAssociationStep(2)">Continuar</button>
              </div>
              <ng-template #noDocs>
                <p class="text-muted mb-0">No hay documentos asociados.</p>
              </ng-template>
            </div>

            <form
              class="admin-panel mt-3"
              *ngIf="isAdminMode && adminTab === 'gestion' && permissions.hasPermission('inscripciones:write')"
              [formGroup]="inscripcionAdminForm"
              (ngSubmit)="crearInscripcion()"
            >
              <h3 class="section-title">Gestion de inscripcion</h3>
              <label class="form-label">Titulo</label>
              <input class="form-control" formControlName="titulo" />
              <label class="form-label mt-2">Formulario reutilizable</label>
              <select class="form-select" formControlName="formularioId">
                <option value="">Formulario propio de esta inscripcion</option>
                <option *ngFor="let formulario of formularios" [value]="formulario.id">
                  {{ formulario.nombre }} ({{ formulario.campos.length }} campo(s))
                </option>
              </select>
              <div class="d-flex gap-2 mt-2 flex-wrap">
                <button class="ux-btn ux-btn-light" type="button" [disabled]="loading" (click)="abrirFormularioContextual()">
                  {{ inscripcionAdminForm.value.formularioId ? 'Editar formulario seleccionado' : 'Crear formulario reutilizable' }}
                </button>
              </div>
              <p class="text-muted small mb-0 mt-1">Abre el editor completo del formulario. Al guardarlo se asociara automaticamente a esta inscripcion.</p>
              <label class="form-label mt-2">Actividad vinculada</label>
              <select class="form-select" formControlName="actividadId">
                <option value="">Sin actividad vinculada</option>
                <option *ngFor="let actividad of actividades" [value]="actividad.id">{{ actividad.titulo }}</option>
              </select>
              <div class="row g-2 mt-1">
                <div class="col">
                  <label class="form-label">Publicacion</label>
                  <input type="date" class="form-control" formControlName="fechaPublicacion" />
                </div>
                <div class="col">
                  <label class="form-label">Fecha limite</label>
                  <input type="date" class="form-control" formControlName="fechaLimite" />
                </div>
              </div>
              <div class="d-flex gap-3 mt-3">
                <label class="form-check">
                  <input type="checkbox" class="form-check-input" formControlName="adultos" />
                  Adultos
                </label>
                <label class="form-check">
                  <input type="checkbox" class="form-check-input" formControlName="infantiles" />
                  Infantiles
                </label>
              </div>
              <div class="d-flex gap-2 mt-3 flex-wrap">
                <button class="ux-btn" type="submit" [disabled]="loading">Guardar</button>
                <button class="ux-btn ux-btn-secondary" type="button" *ngIf="inscription.estado === 'abierta'" [disabled]="loading" (click)="cambiarEstadoInscripcion('cerrada')">
                  Desactivar
                </button>
                <button class="ux-btn ux-btn-secondary" type="button" *ngIf="inscription.estado === 'cerrada'" [disabled]="loading" (click)="cambiarEstadoInscripcion('abierta')">
                  Activar
                </button>
                <button class="ux-btn ux-btn-light" type="button" [disabled]="loading" (click)="cambiarEstadoInscripcion('archivada')">
                  Archivar
                </button>
                <button class="ux-btn ux-btn-danger" type="button" [disabled]="loading" (click)="borrarInscripcion()">
                  Borrar definitivamente
                </button>
              </div>
            </form>

            <section class="admin-panel mt-3" *ngIf="isAdminMode && adminTab === 'inscritos'">
              <div class="d-flex justify-content-between align-items-start gap-2 flex-wrap mb-3">
                <div>
                  <h3 class="section-title mb-1">Asociaciones inscritas</h3>
                  <p class="text-muted mb-0">{{ entradas.length }} entrada(s) registradas.</p>
                </div>
                <div class="d-flex gap-2 flex-wrap">
                  <button class="ux-btn ux-btn-light ux-btn-sm" type="button" [disabled]="!entradas.length" (click)="imprimirTodas(inscription)">Imprimir todas</button>
                  <button class="ux-btn ux-btn-light ux-btn-sm" type="button" [disabled]="!entradas.length" (click)="descargarTodas(inscription, 'csv')">Excel</button>
                  <button class="ux-btn ux-btn-light ux-btn-sm" type="button" [disabled]="!entradas.length" (click)="descargarTodas(inscription, 'pdf')">PDF</button>
                </div>
              </div>

              <div class="entries-table" *ngIf="entradas.length; else noEntradas">
                <div class="entries-row header">
                  <span>Asociacion</span>
                  <span>Numero</span>
                  <span>Estado</span>
                  <span>Fecha</span>
                  <span>Acciones</span>
                </div>
                <div class="entries-row" *ngFor="let entrada of entradas">
                  <span>{{ entrada.asociacionNombre || ('Asociacion ' + entrada.asociacionId) }}</span>
                  <span>{{ entrada.numero }}</span>
                  <span><select class="form-select form-select-sm" [ngModel]="entrada.estado" [disabled]="loading || entrada.estado === 'retirada_solicitada' || entrada.estado === 'retirada'" (ngModelChange)="cambiarEstadoEntrada(entrada, $event)">
                    <option value="recibida">Recibida</option><option value="en_revision">En revisi\xF3n</option><option value="con_incidencias">Con incidencias</option><option value="validada">Validada</option><option value="rechazada">Rechazada</option>
                    <option value="retirada_solicitada">Retirada solicitada</option><option value="retirada">Retirada</option>
                  </select></span>
                  <span>{{ entrada.fechaEntrada | date : 'dd/MM/y HH:mm' }}</span>
                  <span class="entry-actions">
                    <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="verEntrada(entrada)">Ver detalle</button>
                    <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="imprimirEntrada(entrada)">Imprimir</button>
                    <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="descargarEntrada(entrada, 'csv')">Excel</button>
                    <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="descargarEntrada(entrada, 'pdf')">PDF</button>
                    <button class="ux-btn ux-btn-secondary ux-btn-sm" type="button" *ngIf="entrada.estado === 'retirada_solicitada'" [disabled]="loading" (click)="resolverRetirada(entrada, true)">Aprobar retirada</button>
                    <button class="ux-btn ux-btn-light ux-btn-sm" type="button" *ngIf="entrada.estado === 'retirada_solicitada'" [disabled]="loading" (click)="resolverRetirada(entrada, false)">Rechazar retirada</button>
                  </span>
                </div>
              </div>
              <ng-template #noEntradas>
                <p class="text-muted mb-0">Todavia no hay asociaciones inscritas.</p>
              </ng-template>

              <div class="entry-detail" *ngIf="selectedEntrada as entrada">
                <div class="d-flex justify-content-between gap-2 flex-wrap mb-2">
                  <div>
                    <p class="ux-overline mb-1">Detalle</p>
                    <h4 class="h6 mb-0">{{ entrada.numero }} - {{ entrada.asociacionNombre || ('Asociacion ' + entrada.asociacionId) }}</h4>
                  </div>
                  <div class="d-flex gap-2 flex-wrap">
                    <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="imprimirEntrada(entrada)">Imprimir</button>
                    <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="descargarEntrada(entrada, 'csv')">Excel</button>
                    <button class="ux-btn ux-btn-light ux-btn-sm" type="button" (click)="descargarEntrada(entrada, 'pdf')">PDF</button>
                  </div>
                </div>
                <dl class="entry-data">
                  <ng-container *ngFor="let field of inscription.campos">
                    <dt>{{ field.label }}</dt>
                    <dd>{{ entradaCampoLabel(entrada, field) }}</dd>
                  </ng-container>
                </dl>
                <section class="mt-3">
                  <h5 class="h6">Adjuntos de la entrada</h5>
                  <input class="form-control form-control-sm mb-2" type="file" multiple [disabled]="loading" (change)="onAdjuntosEntradaChange($event, entrada)" />
                  <div class="document-list" *ngIf="adjuntosEntrada.length; else noEntryAttachments">
                    <button class="document-item" type="button" *ngFor="let adjunto of adjuntosEntrada" (click)="abrirDocumento(adjunto)">
                      {{ adjunto.mimeType === 'application/pdf' ? 'PDF \xB7 ' : (adjunto.mimeType || '').startsWith('image/') ? 'Imagen \xB7 ' : 'Archivo \xB7 ' }}{{ adjunto.originalName || adjunto.fileName }}
                    </button>
                  </div>
                  <ng-template #noEntryAttachments><p class="text-muted mb-0">No hay adjuntos para esta entrada.</p></ng-template>
                </section>
                <section class="mt-3" *ngIf="entrada.eventos?.length"><h5 class="h6">Historial</h5><ul class="mb-0"><li *ngFor="let evento of entrada.eventos">{{ evento.createdAt | date:'dd/MM/yyyy HH:mm' }} \xB7 {{ evento.actor }} \xB7 {{ evento.detalle || evento.tipo }}</li></ul></section>
                <app-incidencias-panel scope="inscripcion" [scopeId]="entrada.id"></app-incidencias-panel>
              </div>
            </section>

            <section class="summary-panel mt-3" *ngIf="!isAdminMode && associationTab === 'formulario' && associationMode === 'summary' && miEntrada as entrada">
              <div class="d-flex justify-content-between align-items-start gap-2 flex-wrap mb-3">
                <div>
                  <p class="ux-overline mb-1">Inscripcion registrada</p>
                  <h3 class="section-title mb-1">{{ inscription.titulo }}</h3>
                  <p class="text-muted mb-0">{{ entrada.numero }} - {{ entrada.fechaEntrada | date : 'dd/MM/y HH:mm' }}</p>
                </div>
                <button class="ux-btn" type="button" (click)="cerrarResumen()">Cerrar</button>
                <button class="ux-btn ux-btn-secondary" type="button" (click)="descargarJustificanteEntrada(entrada)">Justificante PDF</button>
              </div>
              <dl class="entry-data">
                <dt>Participantes</dt>
                <dd>{{ entradaParticipantesLabel(entrada) }}</dd>
                <ng-container *ngFor="let field of inscription.campos">
                  <dt>{{ field.label }}</dt>
                  <dd>{{ entradaCampoLabel(entrada, field) }}</dd>
                </ng-container>
              </dl>
              <section class="mt-3" *ngIf="adjuntosEntrada.length">
                <h4 class="h6">Adjuntos de la entrada</h4>
                <div class="document-list"><button class="document-item" type="button" *ngFor="let adjunto of adjuntosEntrada" (click)="abrirDocumento(adjunto)">{{ adjunto.originalName || adjunto.fileName }}</button></div>
              </section>
            </section>

            <section class="summary-panel mt-3" *ngIf="!isAdminMode && associationTab === 'formulario' && associationMode === 'view' && miEntrada as entrada">
              <div class="d-flex justify-content-between align-items-start gap-2 flex-wrap mb-3">
                <div>
                  <p class="ux-overline mb-1">Inscripcion presentada</p>
                  <h3 class="section-title mb-1">{{ inscription.titulo }}</h3>
                  <p class="text-muted mb-0">{{ entrada.numero }} - {{ entrada.fechaEntrada | date : 'dd/MM/y HH:mm' }}</p>
                </div>
                <button class="ux-btn" type="button" *ngIf="puedeModificarMiEntrada()" [disabled]="accionesAsociacionBloqueadasPorEjercicio" (click)="modificarMiInscripcion()">
                  Modificar inscripcion
                </button>
                <button class="ux-btn ux-btn-danger" type="button" *ngIf="puedeModificarMiEntrada()" [disabled]="loading" (click)="solicitarBorradoMiEntrada()">Borrar inscripci\xF3n</button>
                <button class="ux-btn ux-btn-danger" type="button" *ngIf="puedeSolicitarRetirada(entrada)" [disabled]="loading" (click)="solicitarRetirada(entrada)">
                  Solicitar retirada
                </button>
              </div>
              <dl class="entry-data">
                <dt>Participantes</dt>
                <dd>{{ entradaParticipantesLabel(entrada) }}</dd>
                <ng-container *ngFor="let field of inscription.campos">
                  <dt>{{ field.label }}</dt>
                  <dd>{{ entradaCampoLabel(entrada, field) }}</dd>
                </ng-container>
              </dl>
              <section class="mt-3" *ngIf="adjuntosEntrada.length">
                <h4 class="h6">Adjuntos de la entrada</h4>
                <div class="document-list"><button class="document-item" type="button" *ngFor="let adjunto of adjuntosEntrada" (click)="abrirDocumento(adjunto)">{{ adjunto.originalName || adjunto.fileName }}</button></div>
              </section>
              <p class="text-muted mb-0 mt-2" *ngIf="entrada.estado === 'validada'">Validada: no se puede modificar ni borrar.</p>
              <p class="text-muted mb-0 mt-2" *ngIf="entrada.estado !== 'validada' && !isWithinDeadline(inscription)">Plazo cerrado: no se puede modificar ni borrar.</p>
              <p class="text-muted mb-0 mt-2" *ngIf="entrada.estado === 'retirada_solicitada'">Retirada pendiente de validaci\xF3n administrativa.</p>
              <p class="text-muted mb-0 mt-2" *ngIf="entrada.estado === 'retirada'">Inscripci\xF3n retirada.</p>
            </section>

            <form [formGroup]="form" class="form-grid mt-3" *ngIf="!isAdminMode && associationTab === 'formulario' && associationMode === 'edit'">
              <h3 class="section-title">Formulario</h3>
              <div class="field-grid">
                <ng-container *ngFor="let field of inscription.campos">
                    <div class="field" [class.full]="field.type === 'textarea'">
                      <label class="form-label" [for]="fieldInputId(field)">
                        {{ field.label }}
                        <span *ngIf="isRequiredField(field)" class="required-indicator" aria-hidden="true">*</span>
                        <span *ngIf="isRequiredField(field)" class="visually-hidden"> (obligatorio)</span>
                      </label>
                      <ng-container [ngSwitch]="field.type">
                        <textarea *ngSwitchCase="'textarea'" class="form-control" rows="3" [id]="fieldInputId(field)" [required]="isRequiredField(field)" [attr.aria-required]="isRequiredField(field) ? 'true' : null" [attr.aria-invalid]="isFieldInvalid(field) ? 'true' : null" [attr.aria-describedby]="isFieldInvalid(field) ? fieldErrorId(field) : null" [formControlName]="field.key"></textarea>
                        <select *ngSwitchCase="'select'" class="form-select" [id]="fieldInputId(field)" [required]="isRequiredField(field)" [attr.aria-required]="isRequiredField(field) ? 'true' : null" [attr.aria-invalid]="isFieldInvalid(field) ? 'true' : null" [attr.aria-describedby]="isFieldInvalid(field) ? fieldErrorId(field) : null" [formControlName]="field.key">
                        <option value="" disabled>Selecciona una opcion</option>
                        <option *ngFor="let opt of field.options ?? []" [value]="opt">{{ opt }}</option>
                      </select>
                        <select *ngSwitchCase="'asociado'" class="form-select" [id]="fieldInputId(field)" [required]="isRequiredField(field)" [attr.aria-required]="isRequiredField(field) ? 'true' : null" [attr.aria-invalid]="isFieldInvalid(field) ? 'true' : null" [attr.aria-describedby]="isFieldInvalid(field) ? fieldErrorId(field) : null" [formControlName]="field.key">
                        <option value="" disabled>Selecciona un asociado</option>
                        <option *ngFor="let person of asociadosForField(field)" [value]="person.id">{{ asociadoLabel(person) }}</option>
                      </select>
                        <select *ngSwitchCase="'asociado_adulto'" class="form-select" [id]="fieldInputId(field)" [required]="isRequiredField(field)" [attr.aria-required]="isRequiredField(field) ? 'true' : null" [attr.aria-invalid]="isFieldInvalid(field) ? 'true' : null" [attr.aria-describedby]="isFieldInvalid(field) ? fieldErrorId(field) : null" [formControlName]="field.key">
                        <option value="" disabled>Selecciona un asociado adulto</option>
                        <option *ngFor="let person of asociadosForField(field)" [value]="person.id">{{ asociadoLabel(person) }}</option>
                      </select>
                        <select *ngSwitchCase="'asociado_infantil'" class="form-select" [id]="fieldInputId(field)" [required]="isRequiredField(field)" [attr.aria-required]="isRequiredField(field) ? 'true' : null" [attr.aria-invalid]="isFieldInvalid(field) ? 'true' : null" [attr.aria-describedby]="isFieldInvalid(field) ? fieldErrorId(field) : null" [formControlName]="field.key">
                        <option value="" disabled>Selecciona un asociado infantil</option>
                        <option *ngFor="let person of asociadosForField(field)" [value]="person.id">{{ asociadoLabel(person) }}</option>
                      </select>
                        <select *ngSwitchCase="'responsable'" class="form-select" [id]="fieldInputId(field)" [required]="isRequiredField(field)" [attr.aria-required]="isRequiredField(field) ? 'true' : null" [attr.aria-invalid]="isFieldInvalid(field) ? 'true' : null" [attr.aria-describedby]="isFieldInvalid(field) ? fieldErrorId(field) : null" [formControlName]="field.key">
                        <option value="" disabled>Selecciona responsable</option>
                        <option *ngFor="let person of asociadosForField(field)" [value]="person.id">{{ asociadoLabel(person) }}</option>
                      </select>
                        <input *ngSwitchDefault class="form-control" [id]="fieldInputId(field)" [attr.type]="field.type" [required]="isRequiredField(field)" [attr.aria-required]="isRequiredField(field) ? 'true' : null" [attr.aria-invalid]="isFieldInvalid(field) ? 'true' : null" [attr.aria-describedby]="isFieldInvalid(field) ? fieldErrorId(field) : null" [formControlName]="field.key" />
                      </ng-container>
                      <div class="invalid-field" [id]="fieldErrorId(field)" role="alert" *ngIf="isFieldInvalid(field)">
                      Este campo es obligatorio.
                    </div>
                  </div>
                </ng-container>
              </div>
            </form>

            <section class="summary-panel mt-3" *ngIf="!isAdminMode && associationTab === 'asociados' && associationMode !== 'edit' && miEntrada as entrada">
              <h3 class="section-title">Asociados inscritos</h3>
              <p class="text-muted mb-0">{{ entradaParticipantesLabel(entrada) }}</p>
            </section>

            <div class="participants mt-3" *ngIf="!isAdminMode && associationTab === 'asociados' && associationMode === 'edit'">
              <div class="d-flex align-items-center justify-content-between flex-wrap gap-2 mb-2">
                <h3 class="section-title mb-0">Seleccionar asociados</h3>
                <span class="text-muted small">{{ selectedParticipants.size }} seleccionado(s)</span>
              </div>

              <div class="participant-toolbar">
                <div class="participant-tabs" role="tablist" aria-label="Tipos de asociados">
                  <button
                    type="button"
                    class="tab-button"
                    [class.active]="participantTab === 'adulto'"
                    [disabled]="!inscription.tiposPermitidos.includes('adulto')"
                    (click)="setParticipantTab('adulto')"
                  >
                    Adultos
                  </button>
                  <button
                    type="button"
                    class="tab-button"
                    [class.active]="participantTab === 'infantil'"
                    [disabled]="!inscription.tiposPermitidos.includes('infantil')"
                    (click)="setParticipantTab('infantil')"
                  >
                    Infantiles
                  </button>
                </div>

                <div class="participant-filters">
                  <label class="filter-field">
                    <span>Buscar</span>
                    <input
                      class="form-control"
                      type="search"
                      [(ngModel)]="participantSearch"
                      [ngModelOptions]="{ standalone: true }"
                      (ngModelChange)="onParticipantSearchChange()"
                      placeholder="Nombre, cargo o DNI"
                    />
                  </label>
                  <label class="filter-field">
                    <span>Ordenar</span>
                    <select
                      class="form-select"
                      [(ngModel)]="participantSort"
                      [ngModelOptions]="{ standalone: true }"
                      (ngModelChange)="onParticipantSortChange()"
                    >
                      <option value="nombre-asc">Nombre A-Z</option>
                      <option value="nombre-desc">Nombre Z-A</option>
                      <option value="cargo-asc">Cargo A-Z</option>
                    </select>
                  </label>
                </div>
              </div>

              <label class="select-all">
                <input type="checkbox" [checked]="allTabParticipantsSelected" (change)="toggleAllTabParticipants()" />
                Seleccionar/deseleccionar todos los asociados de esta pesta\xF1a
              </label>

              <div class="participant-list">
                <label class="participant-item" *ngFor="let person of pagedParticipants">
                  <input type="checkbox" [checked]="isParticipantSelected(person)" (change)="toggleParticipant(person)" />
                  <div class="info">
                    <p class="name mb-0">{{ person.nombre }} {{ person.apellidos }}</p>
                    <small class="text-muted">{{ person.cargo || 'Sin cargo' }} - {{ person.tipo }}</small>
                  </div>
                </label>
              </div>

              <div class="participant-pagination" *ngIf="filteredParticipants.length">
                <div class="text-muted small">
                  {{ participantRangeStart }} - {{ participantRangeEnd }} de {{ filteredParticipants.length }}
                </div>
                <label class="page-size">
                  <span>Por pagina</span>
                  <select
                    class="form-select form-select-sm"
                    [(ngModel)]="participantPageSize"
                    [ngModelOptions]="{ standalone: true }"
                    (ngModelChange)="onParticipantPageSizeChange()"
                  >
                    <option *ngFor="let size of participantPageSizes" [ngValue]="size">{{ size }}</option>
                  </select>
                </label>
                <div class="page-actions">
                  <button class="ux-btn ux-btn-light ux-btn-sm" type="button" [disabled]="participantPage === 1" (click)="previousParticipantPage()">
                    Anterior
                  </button>
                  <span class="small text-muted">Pagina {{ participantPage }} de {{ participantTotalPages }}</span>
                  <button class="ux-btn ux-btn-light ux-btn-sm" type="button" [disabled]="participantPage === participantTotalPages" (click)="nextParticipantPage()">
                    Siguiente
                  </button>
                </div>
              </div>
              <p class="text-muted mb-0 mt-2" *ngIf="!filteredParticipants.length">No hay asociados disponibles con los filtros actuales.</p>
            </div>

            <div class="actions d-flex flex-wrap gap-2 mt-3" *ngIf="!isAdminMode && associationMode === 'edit'">
              <button type="button" class="ux-btn" [disabled]="!canSubmit || accionesAsociacionBloqueadasPorEjercicio" (click)="submit()">
                <i class="bi bi-send me-1"></i>
                {{ miEntrada ? 'Guardar cambios' : 'Inscribirse' }}
              </button>
              <button type="button" class="ux-btn ux-btn-secondary" *ngIf="miEntrada" (click)="associationMode = 'view'">
                Cancelar
              </button>
            </div>
          </ng-container>

          <p class="text-muted mb-0" *ngIf="!selectedInscription && !createMode">
            No se ha podido cargar el detalle de la inscripcion.
          </p>
        </section>
      </div>
  </div>
</section>

<div class="formulario-backdrop" *ngIf="showFormularioDialog" (click)="cerrarFormularioContextual()"></div>
<section class="formulario-dialog" *ngIf="showFormularioDialog" role="dialog" aria-modal="true" aria-labelledby="formularioContextualTitulo" (click)="$event.stopPropagation()">
  <header class="formulario-dialog-header">
    <div>
      <p class="ux-overline mb-1">Inscripcion</p>
      <h2 id="formularioContextualTitulo" class="h5 mb-0">{{ formularioContextual() ? 'Editar formulario reutilizable' : 'Crear formulario reutilizable' }}</h2>
    </div>
    <button class="btn btn-outline-secondary btn-sm" type="button" [disabled]="loading" (click)="cerrarFormularioContextual()">Cerrar</button>
  </header>
  <div class="formulario-dialog-body">
    <app-formularios
      [contextual]="true"
      [formularioInicial]="formularioContextual()"
      [camposIniciales]="camposFormularioContextual()"
      (formularioGuardado)="asociarFormularioGuardado($event)"
      (cancelado)="cerrarFormularioContextual()"
    ></app-formularios>
  </div>
</section>

<app-confirm-dialog
  *ngIf="confirmDelete"
  title="Borrar inscripci\xF3n"
  message="Esta acci\xF3n borrar\xE1 definitivamente la inscripci\xF3n. No se puede deshacer."
  confirmLabel="Borrar inscripci\xF3n"
  (cancel)="confirmDelete = false"
  (confirmed)="confirmarBorradoInscripcion()"
></app-confirm-dialog>

<app-confirm-dialog
  *ngIf="confirmDeleteEntry"
  title="Borrar inscripci\xF3n presentada"
  message="Se eliminar\xE1 la entrada y su historial. Esta acci\xF3n no se puede deshacer."
  confirmLabel="Borrar inscripci\xF3n"
  (cancel)="confirmDeleteEntry = false"
  (confirmed)="confirmarBorradoMiEntrada()"
></app-confirm-dialog>

`, styles: ["/* src/app/inscripciones/inscripciones.component.scss */\n.inscripciones {\n  overflow: hidden;\n}\n.inscripciones-body {\n  padding: clamp(1.25rem, 3vw, 2.25rem);\n}\n.page-head,\n.section-head {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 1rem;\n  flex-wrap: wrap;\n}\n.layout {\n  min-height: 420px;\n}\n.detail,\n.admin-panel,\n.summary-panel,\n.documents,\n.participants,\n.entry-detail {\n  border: 1px solid var(--ffsj-line);\n  border-radius: 18px;\n  background: #fff;\n}\n.detail {\n  padding: clamp(1.1rem, 2vw, 1.5rem);\n  display: flex;\n  flex-direction: column;\n  gap: 1.15rem;\n  min-height: 100%;\n}\n.list-page {\n  max-width: 1080px;\n}\n.admin-panel,\n.summary-panel,\n.documents,\n.participants,\n.entry-detail {\n  padding: 1rem;\n}\n.documents,\n.participants,\n.entry-detail {\n  background: #fbfcfe;\n}\n.documents {\n  background: #eff6ff;\n  border-color: #bfdbfe;\n}\n.section-title {\n  color: var(--ffsj-ink);\n  font-size: 1.05rem;\n  font-weight: 900;\n}\n.detail-title {\n  color: var(--ffsj-red);\n  font-size: 1.35rem;\n  font-weight: 900;\n}\n.type-badge {\n  border-radius: 999px;\n  border: 1px solid #fecdd3;\n  background: var(--ffsj-soft-red);\n  color: var(--ffsj-red);\n  font-weight: 850;\n  padding: 0.45rem 0.7rem;\n}\n.inscription-list {\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n  max-height: calc(100vh - 250px);\n  overflow-y: auto;\n  padding-right: 0.25rem;\n}\n.inscription-filters {\n  display: grid;\n  grid-template-columns: minmax(220px, 2fr) repeat(3, minmax(150px, 1fr)) auto;\n  align-items: end;\n  gap: 0.75rem;\n  margin: 1rem 0;\n  padding: 0.8rem;\n  border: 1px solid var(--ffsj-line);\n  border-radius: 14px;\n  background: var(--ffsj-soft-gray);\n}\n.inscription-filters label {\n  display: grid;\n  gap: 0.25rem;\n  min-width: 0;\n  color: var(--ffsj-muted);\n  font-size: 0.82rem;\n  font-weight: 800;\n}\n.filter-action {\n  display: flex;\n  align-items: end;\n  min-height: 31px;\n}\n@media (max-width: 960px) {\n  .inscription-filters {\n    grid-template-columns: repeat(2, minmax(180px, 1fr));\n  }\n}\n@media (max-width: 560px) {\n  .inscription-filters {\n    grid-template-columns: 1fr;\n  }\n  .filter-action .ux-btn {\n    width: 100%;\n  }\n}\n.inscription-badges {\n  display: flex;\n  gap: 0.4rem;\n  flex-wrap: wrap;\n  margin-top: 0.45rem;\n}\n.availability-badge,\n.participation-badge {\n  border-radius: 999px;\n  padding: 0.25rem 0.55rem;\n  font-size: 0.75rem;\n  font-weight: 850;\n  background: var(--ffsj-soft-green);\n  color: #166534;\n}\n.availability-badge.closed {\n  background: var(--ffsj-soft-orange);\n  color: #9a3412;\n}\n.participation-badge {\n  background: var(--ffsj-soft-gray);\n  color: var(--ffsj-muted);\n}\n.participation-badge.registered {\n  background: var(--ffsj-soft-blue);\n  color: #1d4ed8;\n}\n.list-item {\n  border: 1px solid var(--ffsj-line);\n  background: #fff;\n  border-radius: 16px;\n  padding: 0.9rem;\n  text-align: left;\n  display: flex;\n  align-items: center;\n  gap: 0.85rem;\n  width: 100%;\n  cursor: pointer;\n  transition:\n    border-color 0.15s ease,\n    box-shadow 0.15s ease,\n    transform 0.1s ease;\n}\n.list-item:hover {\n  transform: translateY(-2px);\n  border-color: #fecdd3;\n  box-shadow: 0 12px 28px rgba(16, 24, 40, 0.08);\n}\n.list-item.active {\n  border-color: var(--ffsj-red);\n  box-shadow: 0 0 0 3px rgba(178, 31, 45, 0.12);\n}\n.list-actions,\n.entry-actions {\n  display: flex;\n  gap: 0.4rem;\n  flex-wrap: wrap;\n  justify-content: flex-end;\n  margin-left: auto;\n}\n.title {\n  color: var(--ffsj-ink);\n  font-weight: 900;\n}\n.subtitle {\n  font-size: 0.95rem;\n}\n.detail-header {\n  border-bottom: 1px solid var(--ffsj-line);\n  padding-bottom: 0.8rem;\n}\n.admin-tabs,\n.participant-tabs {\n  display: flex;\n  gap: 0.5rem;\n  flex-wrap: wrap;\n}\n.admin-tabs {\n  border-bottom: 1px solid var(--ffsj-line);\n  padding-bottom: 0.75rem;\n}\n.tab-button {\n  border: 1px solid var(--ffsj-line);\n  border-radius: 999px;\n  background: var(--ffsj-soft-gray);\n  color: var(--ffsj-ink);\n  font-weight: 850;\n  padding: 0.5rem 0.9rem;\n}\n.tab-button.active {\n  background: var(--ffsj-red);\n  border-color: var(--ffsj-red);\n  color: #fff;\n}\n.tab-button:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n.inscription-steps {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.55rem;\n  margin: 0.25rem 0 0.5rem;\n}\n.step-pill {\n  border: 0;\n  border-radius: 999px;\n  background: var(--ffsj-soft-gray);\n  color: #667085;\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  min-height: 42px;\n  padding: 0.48rem 0.85rem 0.48rem 0.55rem;\n  font-weight: 900;\n}\n.step-pill span {\n  width: 26px;\n  height: 26px;\n  border-radius: 999px;\n  background: #fff;\n  color: #667085;\n  display: grid;\n  place-items: center;\n  font-weight: 900;\n}\n.step-pill.active {\n  background: var(--ffsj-soft-red);\n  color: var(--ffsj-red);\n}\n.step-pill.active span {\n  color: var(--ffsj-red);\n}\n.step-pill:disabled {\n  opacity: 0.55;\n  cursor: not-allowed;\n}\n.document-list,\n.form-grid,\n.linked-form {\n  display: grid;\n  gap: 0.8rem;\n}\n.document-item {\n  border: 1px solid var(--ffsj-line);\n  border-radius: 12px;\n  background: #fff;\n  color: var(--ffsj-red);\n  font-weight: 850;\n  padding: 0.65rem 0.8rem;\n  text-decoration: none;\n}\n.field-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n  gap: 1rem;\n}\n.field.full {\n  grid-column: 1/-1;\n}\n.required-indicator {\n  color: var(--ffsj-red);\n  font-weight: 900;\n  margin-left: 0.18rem;\n}\n.participant-toolbar {\n  display: grid;\n  grid-template-columns: minmax(220px, auto) 1fr;\n  gap: 1rem;\n  align-items: end;\n  margin-bottom: 0.85rem;\n}\n.participant-filters {\n  display: grid;\n  grid-template-columns: minmax(220px, 1fr) minmax(170px, 220px);\n  gap: 0.75rem;\n}\n.filter-field,\n.page-size {\n  display: grid;\n  gap: 0.25rem;\n  color: var(--ffsj-muted);\n  font-size: 0.85rem;\n  font-weight: 850;\n}\n.select-all {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.5rem;\n  margin-bottom: 0.85rem;\n  font-weight: 850;\n}\n.select-all input,\n.participant-item input {\n  width: 18px;\n  height: 18px;\n}\n.participant-list {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n  gap: 0.75rem;\n}\n.participant-item {\n  display: flex;\n  gap: 0.6rem;\n  align-items: center;\n  padding: 0.65rem 0.75rem;\n  border: 1px solid var(--ffsj-line);\n  border-radius: 14px;\n  background: #fff;\n  cursor: pointer;\n}\n.participant-item .name {\n  color: var(--ffsj-ink);\n  font-weight: 850;\n}\n.participant-pagination {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1rem;\n  flex-wrap: wrap;\n  margin-top: 1rem;\n}\n.entries-table {\n  display: grid;\n  border: 1px solid var(--ffsj-line);\n  border-radius: 14px;\n  overflow: hidden;\n}\n.entries-row {\n  display: grid;\n  grid-template-columns: minmax(180px, 1.4fr) minmax(120px, 0.8fr) minmax(100px, 0.7fr) minmax(130px, 0.8fr) minmax(280px, 1.4fr);\n  gap: 0.75rem;\n  align-items: center;\n  padding: 0.8rem;\n  border-bottom: 1px solid var(--ffsj-line);\n}\n.entries-row:last-child {\n  border-bottom: 0;\n}\n.entries-row.header {\n  background: var(--ffsj-soft-gray);\n  color: var(--ffsj-ink);\n  font-weight: 900;\n}\n.entry-data {\n  display: grid;\n  grid-template-columns: minmax(160px, 260px) 1fr;\n  gap: 0.55rem 1rem;\n  margin: 0;\n}\n.entry-data dt {\n  color: var(--ffsj-muted);\n  font-weight: 900;\n}\n.entry-data dd {\n  margin: 0;\n}\n.page-actions {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n.actions .ux-btn,\n.actions .btn {\n  font-weight: 850;\n}\n.formulario-backdrop {\n  position: fixed;\n  inset: 0;\n  z-index: 1050;\n  background: rgba(16, 24, 40, 0.48);\n}\n.formulario-dialog {\n  position: fixed;\n  z-index: 1051;\n  inset: 1rem;\n  width: min(1080px, 100vw - 2rem);\n  max-height: calc(100vh - 2rem);\n  margin: auto;\n  overflow: auto;\n  border-radius: 18px;\n  background: #fff;\n  box-shadow: 0 24px 60px rgba(16, 24, 40, 0.28);\n}\n.formulario-dialog-header {\n  position: sticky;\n  top: 0;\n  z-index: 1;\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 1rem;\n  padding: 1rem 1.25rem;\n  border-bottom: 1px solid var(--ffsj-line);\n  background: #fff;\n}\n.formulario-dialog-body {\n  padding: 1rem;\n}\n@media (max-width: 991px) {\n  .inscription-list {\n    max-height: none;\n  }\n  .participant-toolbar,\n  .participant-filters {\n    grid-template-columns: 1fr;\n  }\n  .entries-row {\n    grid-template-columns: 1fr;\n  }\n  .list-item {\n    align-items: flex-start;\n    flex-direction: column;\n  }\n  .list-actions,\n  .entry-actions {\n    justify-content: flex-start;\n    margin-left: 0;\n  }\n}\n/*# sourceMappingURL=inscripciones.component-DX6C5SOY.css.map */\n"] }]
