// src/app/core/admin.guard.ts
var adminGuard = () => {
  const adminAccess = inject2(AdminAccessService);
  const router = inject2(Router);
  return adminAccess.isAdmin() ? true : router.createUrlTree(["/"]);
};

// src/app/core/permission.guard.ts
var permissionGuard = (route) => {
  const permission = route.data?.["permission"];
  const permissions = inject2(PermissionsService);
  const router = inject2(Router);
  if (!permission) {
    return true;
  }
  return permissions.can(permission).pipe(map((canAccess) => {
    if (canAccess) {
      return true;
    }
    return router.createUrlTree(["/"]);
  }));
};

